# ScoutSuite: Multi-cloud security auditing tool
# Install: pip install scoutsuite

# Run AWS audit:
# scout aws --profile my-profile

# Key findings ScoutSuite detects:
misconfig_patterns = {
    "s3_public_access": {
        "description": "S3 bucket allows public read access",
        "severity": "HIGH",
        "check": "Bucket Policy grants public read"
    },
    "iam_admin_policy": {
        "description": "IAM user/role has AdministratorAccess",
        "severity": "HIGH",
        "check": "Policy allows action:* on resource:*"
    },
    "security_group_open": {
        "description": "Security group allows 0.0.0.0/0 ingress",
        "severity": "MEDIUM",
        "check": "Ingress rule with source 0.0.0.0/0"
    },
    "unencrypted_ebs": {
        "description": "EBS volume not encrypted",
        "severity": "MEDIUM",
        "check": "Encrypted flag is False"
    },
    "cloudtrail_not_multi_region": {
        "description": "CloudTrail not enabled in all regions",
        "severity": "LOW",
        "check": "IsMultiRegionTrail is False"
    }
}

for name, config in misconfig_patterns.items():
    print(f'⚠️  {name}: {config["description"]} [{config["severity"]}]')
